1	import { isAdapterType } from "../adapters/registry.js";
2	import { assertPortableRelativePath, portablePathKey } from "../core/paths.js";
3	import { hasUnsafeLineControl, isWellFormedUnicode } from "../core/text.js";
4	import type {
5	  AdapterConfig,
6	  AdapterConfigV1,
7	  AdapterConfigV2,
8	  AdapterSurfaceType,
9	  ContextDocument,
10	  Diagnostic,
11	  LegacyAdapterType,
12	  LoadPolicy,
13	  ProjectConfig,
14	} from "../domain/types.js";
15	import { CONFIG_VERSION, CONFIG_VERSION_2 } from "../domain/types.js";
16	
17	const ID_PATTERN = /^[a-z][a-z0-9-]*$/;
18	const LOAD_POLICIES = new Set<LoadPolicy>(["always", "on-demand"]);
19	const MAX_DOCUMENTS = 256;
20	const MAX_ADAPTERS = 32;
21	const MAX_TRIGGERS = 32;
22	const V1_ADAPTERS = new Set<LegacyAdapterType>(["codex", "claude"]);
23	const V2_ADAPTERS = new Set<AdapterSurfaceType>(["agents", "claude", "gemini"]);
24	
25	export interface DecodeResult {
26	  config?: ProjectConfig;
27	  diagnostics: Diagnostic[];
28	}
29	
30	export function decodeConfig(input: unknown): DecodeResult {
31	  const diagnostics: Diagnostic[] = [];
32	  if (!isRecord(input)) {
33	    return {
34	      diagnostics: [error("E_CONFIG_TYPE", "Configuration must be a YAML mapping.")],
35	    };
36	  }
37	
38	  const version = input["version"];
39	  if (version !== CONFIG_VERSION && version !== CONFIG_VERSION_2) {
40	    diagnostics.push(
41	      error(
42	        "E_CONFIG_VERSION",
43	        `Unsupported configuration version: ${String(version)}. Supported versions: ${CONFIG_VERSION}, ${CONFIG_VERSION_2}.`,
44	        "version",
45	      ),
46	    );
47	  }
48	  const isV2 = version === CONFIG_VERSION_2;
49	  rejectUnknownKeys(
50	    input,
51	    isV2
52	      ? ["version", "project", "documents", "adapters", "continuity", "policies"]
53	      : ["version", "project", "documents", "adapters", "policies"],
54	    "$",
55	    diagnostics,
56	  );
57	
58	  const project = decodeProject(input["project"], diagnostics);
59	  const documents = decodeDocuments(input["documents"], diagnostics);
60	  const adapters = decodeAdapters(input["adapters"], diagnostics, isV2 ? V2_ADAPTERS : V1_ADAPTERS);
61	  const continuity = isV2
62	    ? decodeContinuity(input["continuity"], documents, diagnostics)
63	    : undefined;
64	  const policies = decodePolicies(input["policies"], diagnostics);
65	
66	  if (
67	    diagnostics.some((diagnostic) => diagnostic.level === "error") ||
68	    project === undefined ||
69	    documents === undefined ||
70	    adapters === undefined ||
71	    policies === undefined ||
72	    (isV2 && continuity === undefined)
73	  ) {
74	    return { diagnostics };
75	  }
76	
77	  if (isV2) {
78	    if (continuity === undefined) return { diagnostics };
79	    return {
80	      config: {
81	        version: CONFIG_VERSION_2,
82	        project,
83	        documents,
84	        adapters: adapters as AdapterConfigV2[],
85	        continuity,
86	        policies,
87	      } as ProjectConfig,
88	      diagnostics,
89	    };
90	  }
91	  return {
92	    config: {
93	      version: CONFIG_VERSION,
94	      project,
95	      documents,
96	      adapters: adapters as AdapterConfigV1[],
97	      policies,
98	    } as ProjectConfig,
99	    diagnostics,
100	  };
101	}
102	
103	function decodeProject(
104	  input: unknown,
105	  diagnostics: Diagnostic[],
106	): ProjectConfig["project"] | undefined {
107	  if (!isRecord(input)) {
108	    diagnostics.push(error("E_PROJECT_TYPE", "project must be a mapping.", "project"));
109	    return undefined;
110	  }
111	  rejectUnknownKeys(input, ["name"], "project", diagnostics);
112	  const name = requiredString(input["name"], "project.name", diagnostics, {
113	    singleLine: true,
114	    maxLength: 120,
115	  });
116	  return name === undefined ? undefined : { name };
117	}
118	
119	function decodeDocuments(input: unknown, diagnostics: Diagnostic[]): ContextDocument[] | undefined {
120	  if (!Array.isArray(input) || input.length === 0) {
121	    diagnostics.push(
122	      error("E_DOCUMENTS_TYPE", "documents must be a non-empty sequence.", "documents"),
123	    );
124	    return undefined;
125	  }
126	  if (input.length > MAX_DOCUMENTS) {
127	    diagnostics.push(
128	      error(
129	        "E_DOCUMENT_LIMIT",
130	        `documents must not contain more than ${MAX_DOCUMENTS} entries.`,
131	        "documents",
132	      ),
133	    );
134	  }
135	
136	  const documents: ContextDocument[] = [];
137	  for (const [index, item] of input.slice(0, MAX_DOCUMENTS).entries()) {
138	    const location = `documents[${index}]`;
139	    if (!isRecord(item)) {
140	      diagnostics.push(error("E_DOCUMENT_TYPE", "Document must be a mapping.", location));
141	      continue;
142	    }
143	    rejectUnknownKeys(
144	      item,
145	      ["id", "path", "load", "description", "triggers"],
146	      location,
147	      diagnostics,
148	    );
149	
150	    const id = requiredString(item["id"], `${location}.id`, diagnostics, { maxLength: 64 });
151	    if (id !== undefined && !ID_PATTERN.test(id)) {
152	      diagnostics.push(
153	        error(
154	          "E_DOCUMENT_ID",
155	          "Document id must start with a lowercase letter and contain only lowercase letters, digits, and hyphens.",
156	          `${location}.id`,
157	        ),
158	      );
159	    }
160	    const documentPath = requiredString(item["path"], `${location}.path`, diagnostics);
161	    if (documentPath !== undefined) {
162	      collectPathError(documentPath, `${location}.path`, diagnostics);
163	    }
164	    const load = requiredString(item["load"], `${location}.load`, diagnostics);
165	    if (load !== undefined && !LOAD_POLICIES.has(load as LoadPolicy)) {
166	      diagnostics.push(
167	        error("E_LOAD_POLICY", "load must be 'always' or 'on-demand'.", `${location}.load`),
168	      );
169	    }
170	    const description = requiredString(
171	      item["description"],
172	      `${location}.description`,
173	      diagnostics,
174	      {
175	        singleLine: true,
176	        maxLength: 240,
177	      },
178	    );
179	    const triggers = optionalStringArray(item["triggers"], `${location}.triggers`, diagnostics);
180	
181	    if (
182	      id !== undefined &&
183	      ID_PATTERN.test(id) &&
184	      documentPath !== undefined &&
185	      load !== undefined &&
186	      LOAD_POLICIES.has(load as LoadPolicy) &&
187	      description !== undefined &&
188	      triggers !== null
189	    ) {
190	      const base = {
191	        id,
192	        path: documentPath,
193	        load: load as LoadPolicy,
194	        description,
195	      };
196	      documents.push(triggers === undefined ? base : { ...base, triggers });
197	    }
198	  }
199	
200	  const ids = new Set<string>();
201	  const paths = new Set<string>();
202	  for (const document of documents) {
203	    if (ids.has(document.id)) {
204	      diagnostics.push(error("E_DOCUMENT_ID_DUPLICATE", `Duplicate document id: ${document.id}`));
205	    }
206	    const pathKey = portablePathKey(document.path);
207	    if (paths.has(pathKey)) {
208	      diagnostics.push(
209	        error("E_DOCUMENT_PATH_DUPLICATE", `Duplicate document path: ${document.path}`),
210	      );
211	    }
212	    ids.add(document.id);
213	    paths.add(pathKey);
214	  }
215	  if (!documents.some((document) => document.load === "always")) {
216	    diagnostics.push(error("E_ALWAYS_DOCUMENT", "At least one document must use load: always."));
217	  }
218	
219	  return documents;
220	}
221	
222	function decodeAdapters(
223	  input: unknown,
224	  diagnostics: Diagnostic[],
225	  allowedTypes: ReadonlySet<string>,
226	): AdapterConfig[] | undefined {
227	  if (!Array.isArray(input) || input.length === 0) {
228	    diagnostics.push(
229	      error("E_ADAPTERS_TYPE", "adapters must be a non-empty sequence.", "adapters"),
230	    );
231	    return undefined;
232	  }
233	  if (input.length > MAX_ADAPTERS) {
234	    diagnostics.push(
235	      error(
236	        "E_ADAPTER_LIMIT",
237	        `adapters must not contain more than ${MAX_ADAPTERS} entries.`,
238	        "adapters",
239	      ),
240	    );
241	  }
242	
243	  const adapters: AdapterConfig[] = [];
244	  for (const [index, item] of input.slice(0, MAX_ADAPTERS).entries()) {
245	    const location = `adapters[${index}]`;
246	    if (!isRecord(item)) {
247	      diagnostics.push(error("E_ADAPTER_TYPE", "Adapter must be a mapping.", location));
248	      continue;
249	    }
250	    rejectUnknownKeys(item, ["type", "output"], location, diagnostics);
251	    const type = requiredString(item["type"], `${location}.type`, diagnostics);
252	    if (type !== undefined && (!isAdapterType(type) || !allowedTypes.has(type))) {
253	      diagnostics.push(
254	        error("E_ADAPTER_KIND", `Unsupported adapter type: ${type}`, `${location}.type`),
255	      );
256	    }
257	    const output = requiredString(item["output"], `${location}.output`, diagnostics);
258	    if (output !== undefined) {
259	      collectPathError(output, `${location}.output`, diagnostics);
260	    }
261	    if (
262	      type !== undefined &&
263	      isAdapterType(type) &&
264	      allowedTypes.has(type) &&
265	      output !== undefined
266	    ) {
267	      adapters.push({ type, output });
268	    }
269	  }
270	
271	  const outputs = new Set<string>();
272	  for (const adapter of adapters) {
273	    const outputKey = portablePathKey(adapter.output);
274	    if (outputs.has(outputKey)) {
275	      diagnostics.push(
276	        error("E_ADAPTER_OUTPUT_DUPLICATE", `Duplicate adapter output: ${adapter.output}`),
277	      );
278	    }
279	    outputs.add(outputKey);
280	  }
281	  return adapters;
282	}
283	
284	function decodeContinuity(
285	  input: unknown,
286	  documents: ContextDocument[] | undefined,
287	  diagnostics: Diagnostic[],
288	): { checkpointDocument: string; generateSkills: boolean } | undefined {
289	  if (!isRecord(input)) {
290	    diagnostics.push(error("E_CONTINUITY_TYPE", "continuity must be a mapping.", "continuity"));
291	    return undefined;
292	  }
293	  rejectUnknownKeys(input, ["checkpointDocument", "generateSkills"], "continuity", diagnostics);
294	  const checkpointDocument = requiredString(
295	    input["checkpointDocument"],
296	    "continuity.checkpointDocument",
297	    diagnostics,
298	    { maxLength: 64 },
299	  );
300	  if (checkpointDocument !== undefined && !ID_PATTERN.test(checkpointDocument)) {
301	    diagnostics.push(
302	      error(
303	        "E_CHECKPOINT_DOCUMENT_ID",
304	        "checkpointDocument must be a valid document id.",
305	        "continuity.checkpointDocument",
306	      ),
307	    );
308	  }
309	  const generateSkills = input["generateSkills"];
310	  if (typeof generateSkills !== "boolean") {
311	    diagnostics.push(
312	      error(
313	        "E_CONTINUITY_SKILLS",
314	        "continuity.generateSkills must be a boolean.",
315	        "continuity.generateSkills",
316	      ),
317	    );
318	  }
319	  if (
320	    checkpointDocument !== undefined &&
321	    ID_PATTERN.test(checkpointDocument) &&
322	    documents !== undefined
323	  ) {
324	    const checkpoint = documents.find((document) => document.id === checkpointDocument);
325	    if (checkpoint === undefined) {
326	      diagnostics.push(
327	        error(
328	          "E_CHECKPOINT_DOCUMENT",
329	          `Checkpoint document id does not exist: ${checkpointDocument}`,
330	          "continuity.checkpointDocument",
331	        ),
332	      );
333	    } else if (checkpoint.load !== "always") {
334	      diagnostics.push(
335	        error(
336	          "E_CHECKPOINT_LOAD_POLICY",
337	          "The checkpoint document must use load: always.",
338	          "continuity.checkpointDocument",
339	        ),
340	      );
341	    }
342	  }
343	  return checkpointDocument !== undefined &&
344	    ID_PATTERN.test(checkpointDocument) &&
345	    typeof generateSkills === "boolean" &&
346	    documents?.some((document) => document.id === checkpointDocument && document.load === "always")
347	    ? { checkpointDocument, generateSkills }
348	    : undefined;
349	}
350	
351	function decodePolicies(
352	  input: unknown,
353	  diagnostics: Diagnostic[],
354	): ProjectConfig["policies"] | undefined {
355	  if (!isRecord(input)) {
356	    diagnostics.push(error("E_POLICIES_TYPE", "policies must be a mapping.", "policies"));
357	    return undefined;
358	  }
359	  rejectUnknownKeys(
360	    input,
361	    ["maxAlwaysCharacters", "maxAdapterCharacters"],
362	    "policies",
363	    diagnostics,
364	  );
365	  const alwaysMaximum = boundedInteger(
366	    input["maxAlwaysCharacters"],
367	    "policies.maxAlwaysCharacters",
368	    diagnostics,
369	  );
370	  const adapterMaximum = boundedInteger(
371	    input["maxAdapterCharacters"],
372	    "policies.maxAdapterCharacters",
373	    diagnostics,
374	  );
375	  if (alwaysMaximum === undefined || adapterMaximum === undefined) {
376	    return undefined;
377	  }
378	  return {
379	    maxAlwaysCharacters: alwaysMaximum,
380	    maxAdapterCharacters: adapterMaximum,
381	  };
382	}
383	
384	function boundedInteger(
385	  input: unknown,
386	  location: string,
387	  diagnostics: Diagnostic[],
388	): number | undefined {
389	  if (!Number.isInteger(input) || (input as number) < 1_000 || (input as number) > 100_000) {
390	    diagnostics.push(
391	      error(
392	        "E_CONTEXT_BUDGET",
393	        `${location} must be an integer between 1000 and 100000.`,
394	        location,
395	      ),
396	    );
397	    return undefined;
398	  }
399	  return input as number;
400	}
401	
402	function requiredString(
403	  input: unknown,
404	  location: string,
405	  diagnostics: Diagnostic[],
406	  constraints: { singleLine?: boolean; maxLength?: number } = {},
407	): string | undefined {
408	  if (typeof input !== "string" || input.trim().length === 0) {
409	    diagnostics.push(error("E_REQUIRED_STRING", "Value must be a non-empty string.", location));
410	    return undefined;
411	  }
412	  const value = input;
413	  if (!isWellFormedUnicode(value)) {
414	    diagnostics.push(
415	      error("E_UNICODE", "Value must contain well-formed Unicode scalar values.", location),
416	    );
417	    return undefined;
418	  }
419	  if (value !== value.trim()) {
420	    diagnostics.push(
421	      error(
422	        "E_SURROUNDING_WHITESPACE",
423	        "Value must not contain leading or trailing whitespace.",
424	        location,
425	      ),
426	    );
427	    return undefined;
