40	  for (const [name, value] of Object.entries({
41	    universal: options.universal,
42	    adopt: options.adopt,
43	    check: options.check,
44	    dryRun: options.dryRun,
45	  })) {
46	    if (typeof value !== "boolean") {
47	      throw new CarrylogError(
