49	        `Migration option '${name}' must be boolean.`,
50	        {
51	          exitCode: EXIT_USAGE,
52	        },
53	      );
54	    }
55	  }
56	  await assertLoadedProjectSnapshot(project);
57	  if (project.config.version === 2) {
58	    if (!options.universal) {
59	      return { from: 2, to: 2, changes: [], wrote: false, drift: false };
60	    }
61	    return await enableUniversalV2(project, options);
62	  }
63	
64	  const handoff = project.config.documents.find((document) => document.id === "handoff");
65	  if (handoff === undefined || handoff.load !== "always") {
66	    throw issueError(
67	      "E_CHECKPOINT_REVIEW_REQUIRED",
68	      "v1 migration requires an always-loaded document with id 'handoff'.",
69	      "Add or review the checkpoint document before migrating configuration semantics.",
70	    );
71	  }
72	  const handoffPath = path.posix.join(".agent-context", handoff.path);
73	  const handoffAbsolutePath = resolveProjectPath(project.root, handoffPath);
74	  const existingHandoff = await readTextIfExists(handoffAbsolutePath, { maxBytes: 1024 * 1024 });
75	  if (existingHandoff === undefined) {
76	    throw issueError("E_HANDOFF_MISSING", `Handoff document does not exist: ${handoffPath}`);
77	  }
