83	  }
84	  const prospectiveProject: LoadedProject = Object.freeze({
85	    ...project,
86	    configSource,
87	    config: prospectiveConfig,
88	  });
89	  const overrides = new Map<string, string>([[handoffPath, checkpointContent]]);
90	  const diagnostics = await validateContext(prospectiveProject, overrides);
91	  if (diagnostics.some((diagnostic) => diagnostic.level === "error")) {
92	    throw new CarrylogError("E_MIGRATION_INVALID", "Prospective v2 context is invalid.", {
93	      diagnostics,
94	    });
95	  }
