99	    kind: checkpointContent === existingHandoff ? "unchanged" : "update",
100	    content: checkpointContent,
101	    expectedContent: existingHandoff,
102	  };
103	  const schemaChange = await planPublicSchemaChange(prospectiveProject);
104	  const adapterChanges = await planAdapterChanges(prospectiveProject, options.adopt);
105	  const skillChanges = await planContinuitySkillChanges(prospectiveProject);
106	  const configChange: PlannedChange = {
107	    path: ".agent-context/config.yaml",
108	    kind: "update",
109	    content: configSource,
110	    expectedContent: project.configSource,
111	  };
112	  const changes = [
