162	function planCheckpointContent(existing: string, checkpointPath: string): string {
163	  if (validateCheckpointStructure(existing, checkpointPath).length === 0) return existing;
164	  const legacy = createLegacyHandoffTemplate();
165	  const legacyCrLf = legacy.replace(/\n/g, "\r\n");
166	  const checkpoint = createCheckpointTemplate();
167	  const candidates = [
168	    { legacy, checkpoint },
169	    { legacy: legacyCrLf, checkpoint: checkpoint.replace(/\n/g, "\r\n") },
170	  ];
171	  const snapshotBody = extractHandoffSnapshotBody(existing);
172	  for (const candidate of candidates) {
173	    if (existing === candidate.legacy) return candidate.checkpoint;
174	    if (
175	      snapshotBody !== undefined &&
176	      upsertHandoffSnapshot(candidate.legacy, snapshotBody) === existing
177	    ) {
178	      return upsertHandoffSnapshot(candidate.checkpoint, snapshotBody);
179	    }
180	  }
181	  throw issueError(
182	    "E_CHECKPOINT_REVIEW_REQUIRED",
183	    `Customized handoff cannot be assigned checkpoint semantics automatically: ${checkpointPath}`,
184	    "Create the required Objective, Completed, Verification, Decisions, Risks, and Next action sections, then rerun migration.",
185	  );
